[ExtensionOf(formStr(AVAPTMToolTableListPage))]
final class AVAPTMToolTableListPageFrm_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>AVAICProjProdJumpRef</c> method.
///     AVA - Schneider 14.08.2024
/// </summary>
/// <param name="_formControl">
///     <c>FormControl</c> as type
/// </param>
public void avaICProjProdJumpRef(FormControl _formControl)
{
    KCS_PTMToolTable    locKCS_PTMToolTable;

    locKCS_PTMToolTable = _formControl.formRun().dataSource(formDataSourceStr(AVAPTMToolTableListPage, KCS_PTMToolTable)).cursor();

    if (    locKCS_PTMToolTable.KCS_ProducerUK == ''
        ||  locKCS_PTMToolTable.KCS_ProducerUK == curExt())
    {
        this.avaOpenProjTable(locKCS_PTMToolTable.AVAICProjProd);
    }
    else
    {
        changecompany(locKCS_PTMToolTable.KCS_ProducerUK)
        {
            this.avaOpenProjTable(locKCS_PTMToolTable.AVAICProjProd);
        }
    }
}

