/// <summary>
///     AVA <c>avaOpenProjTable</c> method.
///     AVA - Schneider 14.08.2024
/// </summary>
/// <param name="_projId">
///     <c>ProjId</c> as type
/// </param>
public void avaOpenProjTable(ProjId _projId)
{
    Args            locArgs;
    MenuFunction    locMenuFunction;
    ProjTable       locProjTable;

    locProjTable = ProjTable::find(_projId);
    if(locProjTable.RecId)
    {
        locArgs         = new Args();
        locArgs.record(locProjTable);
        locMenuFunction = new MenuFunction(menuitemDisplayStr(ProjTable), MenuItemType::Display);
        if (    locMenuFunction
            &&  locMenuFunction.checkAccessRights() )
        {
            locMenuFunction.run(locArgs);
        }
    }
}

/// <summary>
///     AVA <c>avaAfterKCS_PTMToolTableCreation</c> method.
///     AVA - Schneider 15.08.2024
/// </summary>
/// <param name="_KCS_PTMToolTable">
///     <c>KCS_PTMToolTable</c> as type
/// </param>
void avaAfterKCS_PTMToolTableCreation(KCS_PTMToolTable _KCS_PTMToolTable)
{
    FormDataSource  locFormDataSource;

    if (_KCS_PTMToolTable.RecId)
    {
        locFormDataSource = KCS_PTMToolTable_ds;
        locFormDataSource.executeQuery();
        locFormDataSource.positionToRecord(_KCS_PTMToolTable);
    }  
}
